import{initializeApp}from"https://www.gstatic.com/firebasejs/9.23.0/firebase-app.js";import{getFirestore,doc,setDoc,increment,onSnapshot,}from"https://www.gstatic.com/firebasejs/9.23.0/firebase-firestore.js";import{getAuth,signInAnonymously}from"https://www.gstatic.com/firebasejs/9.23.0/firebase-auth.js";const{firebase,page}=JSON.parse(document.getElementById("stats-config").textContent),app=initializeApp(firebase),db=getFirestore(app),auth=getAuth(app),viewsId=page&&`views_${page}`,likesId=page&&`likes_${page}`;function storageGet(e){try{return localStorage.getItem(e)}catch{return null}}function storageSet(e,t){try{t?localStorage.setItem(e,!0):localStorage.removeItem(e)}catch{}}function watchCounts(){document.querySelectorAll(".stat-count[data-id]").forEach(e=>{const{collection:t,id:n}=e.dataset;onSnapshot(doc(db,t,n),n=>{e.textContent=(n.exists()?n.data()[t]:0).toLocaleString()},e=>console.error(`Failed to read ${t}/${n}:`,e.message))})}async function recordView(){if(!viewsId||storageGet(viewsId))return;try{await setDoc(doc(db,"views",viewsId),{views:increment(1)},{merge:!0}),storageSet(viewsId,!0)}catch(e){console.error("Failed to record view:",e.message)}}function setupLikeButton(){const t=document.getElementById("like-button");if(!t||!likesId)return;let e=Boolean(storageGet(likesId));const n=()=>{t.setAttribute("aria-pressed",e),t.querySelector(".like-heart").textContent=e?"♥":"♡",t.querySelector(".like-label").textContent=e?"Liked":"Like"};t.addEventListener("click",async()=>{e=!e,n(),t.disabled=!0;try{await setDoc(doc(db,"likes",likesId),{likes:increment(e?1:-1)},{merge:!0}),storageSet(likesId,e)}catch(t){console.error("Failed to update like:",t.message),e=!e,n()}finally{t.disabled=!1}}),n(),t.disabled=!1}watchCounts(),signInAnonymously(auth).then(()=>{recordView(),setupLikeButton()}).catch(e=>console.error("Firebase anonymous sign-in failed:",e.message))